 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seeds = []
    # Each non-background boundary cell launches a ray inward.
    for c in range(w):
        if grid[0][c] != 0:
            seeds.append((0, c, grid[0][c], 1, 0, 'top'))
        if h > 1 and grid[h - 1][c] != 0:
            seeds.append((h - 1, c, grid[h - 1][c], -1, 0, 'bottom'))
    for r in range(1, h - 1):
        if grid[r][0] != 0:
            seeds.append((r, 0, grid[r][0], 0, 1, 'left'))
        if w > 1 and grid[r][w - 1] != 0:
            seeds.append((r, w - 1, grid[r][w - 1], 0, -1, 'right'))

    # Ray endpoints stop at the first perpendicular boundary ray of the same color.
    for r0, c0, color, dr, dc, side in seeds:
        end_r, end_c = (h - 1 if dr > 0 else 0 if dr < 0 else r0,
                        w - 1 if dc > 0 else 0 if dc < 0 else c0)
        if side in ('top', 'bottom'):
            candidates = []
            for rr in range(1, h - 1):
                if (grid[rr][0] == color or grid[rr][w - 1] == color):
                    if (dr > 0 and rr > r0) or (dr < 0 and rr < r0):
                        candidates.append(rr)
            if candidates:
                end_r = min(candidates) if dr > 0 else max(candidates)
        else:
            candidates = []
            for cc in range(1, w - 1):
                if grid[0][cc] == color or grid[h - 1][cc] == color:
                    if (dc > 0 and cc > c0) or (dc < 0 and cc < c0):
                        candidates.append(cc)
            if candidates:
                end_c = min(candidates) if dc > 0 else max(candidates)
        r, c = r0, c0
        while True:
            out[r][c] = color
            if (r, c) == (end_r, end_c):
                break
            r += dr
            c += dc
    return out
